  IF md5((SELECT 'campaigns:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaigns x) || ';' || (SELECT 'campaign_contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_contacts x) || ';' || (SELECT 'campaign_uploads:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x) - 'enrolled_rows' - 'already_in_campaign_rows' - 'opted_out_rows' - 'idempotency_key')::text, '|' ORDER BY (to_jsonb(x) - 'enrolled_rows' - 'already_in_campaign_rows' - 'opted_out_rows' - 'idempotency_key')::text)), '-') FROM public.campaign_uploads x) || ';' || (SELECT 'contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.contacts x) || ';' || (SELECT 'phone_numbers:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.phone_numbers x) || ';' || (SELECT 'agent_configs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.agent_configs x) || ';' || (SELECT 'platform_settings:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.platform_settings x) || ';' || (SELECT 'call_logs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.call_logs x) || ';' || (SELECT 'wallet_transactions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.wallet_transactions x) || ';' || (SELECT 'webhook_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.webhook_events x)) IS DISTINCT FROM current_setting('gate_outbound.data_before', true) THEN
    RAISE EXCEPTION 'GATE_20261124090000_CHECK: existing data changed';
  END IF;
  IF NOT ((SELECT value FROM public.platform_settings WHERE key = 'outbound.calling_paused') = '{"enabled": false}'::jsonb
     AND (SELECT count(*) FROM public.phone_numbers WHERE outbound_enabled) = 0
     AND (SELECT count(*) FROM public.campaigns WHERE status IN ('running', 'scheduled', 'queued')) = 0
     AND (SELECT value -> 'enabled' FROM public.platform_settings WHERE key = 'billing.payment_required') = 'false'::jsonb) THEN
    RAISE EXCEPTION 'GATE_20261124090000_CHECK: outbound safety state changed';
  END IF;
END
$check$;

SELECT json_build_object(
  'applied', '20261124090000',
  'system_identifier', (SELECT system_identifier::text FROM pg_control_system()),
  'database', current_database(),
  'latest_migration', (SELECT max(version) FROM supabase_migrations.schema_migrations),
  'objects_present', ((SELECT string_agg(column_name || ':' || data_type, ',' ORDER BY column_name) FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'campaign_uploads'
          AND column_name IN ('enrolled_rows', 'already_in_campaign_rows', 'opted_out_rows', 'idempotency_key'))
         = 'already_in_campaign_rows:integer,enrolled_rows:integer,idempotency_key:text,opted_out_rows:integer'
     AND (SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_campaign_uploads_org_idempotency_key')
         = 'CREATE UNIQUE INDEX idx_campaign_uploads_org_idempotency_key ON public.campaign_uploads USING btree (organization_id, idempotency_key) WHERE (idempotency_key IS NOT NULL)'
     AND (SELECT prosecdef AND pg_get_userbyid(proowner) = 'postgres' AND proconfig = ARRAY['search_path=""']
            FROM pg_proc WHERE oid = to_regprocedure('public.import_campaign_contacts(uuid, uuid, uuid, text, text, integer, integer, integer, jsonb)'))
     AND has_function_privilege('service_role', 'public.import_campaign_contacts(uuid, uuid, uuid, text, text, integer, integer, integer, jsonb)', 'EXECUTE')
     AND NOT has_function_privilege('anon', 'public.import_campaign_contacts(uuid, uuid, uuid, text, text, integer, integer, integer, jsonb)', 'EXECUTE')
     AND NOT has_function_privilege('authenticated', 'public.import_campaign_contacts(uuid, uuid, uuid, text, text, integer, integer, integer, jsonb)', 'EXECUTE')),
  'existing_data_unchanged', md5((SELECT 'campaigns:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaigns x) || ';' || (SELECT 'campaign_contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.campaign_contacts x) || ';' || (SELECT 'campaign_uploads:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x) - 'enrolled_rows' - 'already_in_campaign_rows' - 'opted_out_rows' - 'idempotency_key')::text, '|' ORDER BY (to_jsonb(x) - 'enrolled_rows' - 'already_in_campaign_rows' - 'opted_out_rows' - 'idempotency_key')::text)), '-') FROM public.campaign_uploads x) || ';' || (SELECT 'contacts:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.contacts x) || ';' || (SELECT 'phone_numbers:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.phone_numbers x) || ';' || (SELECT 'agent_configs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.agent_configs x) || ';' || (SELECT 'platform_settings:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.platform_settings x) || ';' || (SELECT 'call_logs:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.call_logs x) || ';' || (SELECT 'wallet_transactions:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.wallet_transactions x) || ';' || (SELECT 'webhook_events:' || count(*) || ':' || coalesce(md5(string_agg((to_jsonb(x))::text, '|' ORDER BY (to_jsonb(x))::text)), '-') FROM public.webhook_events x)) = current_setting('gate_outbound.data_before', true),
  'lock_timeout', current_setting('lock_timeout'),
  'statement_timeout', current_setting('statement_timeout')
) AS gate_outbound_result;
